DO $patch$ DECLARE d text; anchor text; BEGIN SELECT pg_get_functiondef('public.pm_convert_relative_quote(uuid,date,text)'::regprocedure) INTO d; anchor:='''payment_offset_days'',public.pm_parse_payment_terms(p.payment_terms)'; IF position(anchor in d)=0 THEN RAISE EXCEPTION 'Terms parser conversion anchor missing'; END IF; d:=replace(d,anchor,'''payment_offset_days'',coalesce(public.pm_parse_payment_terms(p.payment_terms),p.payment_offset_days)'); EXECUTE d; END $patch$;
COMMENT ON COLUMN public.pm_payment_schedule_items.payment_terms_review_reason IS 'Conversion-only unreadable/missing terms flag. Required numeric offset preserves the explicit proposal value, never used to forecast an unreadable payment; expected payment date NULL until reviewed or explicitly overridden. Existing rows not backfilled.';